\echo '=== C1 root category (Turystyka) sort name'
EXPLAIN (ANALYZE, BUFFERS) SELECT p.id, p.name, p.tax_class, p.updated_at FROM catalog_product p WHERE (p.primary_category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/%') OR EXISTS (SELECT 1 FROM catalog_product_category pc WHERE pc.product_id = p.id AND pc.category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/%'))) ORDER BY p.name ASC, p.id ASC LIMIT 26;
\echo '=== C1c count root'
EXPLAIN (ANALYZE, BUFFERS) SELECT count(*) FROM (SELECT 1 FROM catalog_product p WHERE (p.primary_category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/%') OR EXISTS (SELECT 1 FROM catalog_product_category pc WHERE pc.product_id = p.id AND pc.category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/%'))) LIMIT 10001) bounded;
\echo '=== C2 leaf category (Termosy, 21k) sort name'
EXPLAIN (ANALYZE, BUFFERS) SELECT p.id, p.name, p.tax_class, p.updated_at FROM catalog_product p WHERE (p.primary_category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/b046c3bb-67cf-575e-85de-475b0a4231db/4b68d4ca-f126-562f-a142-65edd596cc0c/%') OR EXISTS (SELECT 1 FROM catalog_product_category pc WHERE pc.product_id = p.id AND pc.category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/b046c3bb-67cf-575e-85de-475b0a4231db/4b68d4ca-f126-562f-a142-65edd596cc0c/%'))) ORDER BY p.name ASC, p.id ASC LIMIT 26;
\echo '=== C2b leaf sort -updatedAt'
EXPLAIN (ANALYZE, BUFFERS) SELECT p.id, p.name, p.tax_class, p.updated_at FROM catalog_product p WHERE (p.primary_category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/b046c3bb-67cf-575e-85de-475b0a4231db/4b68d4ca-f126-562f-a142-65edd596cc0c/%') OR EXISTS (SELECT 1 FROM catalog_product_category pc WHERE pc.product_id = p.id AND pc.category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/b046c3bb-67cf-575e-85de-475b0a4231db/4b68d4ca-f126-562f-a142-65edd596cc0c/%'))) ORDER BY p.updated_at DESC, p.id DESC LIMIT 26;
\echo '=== C2c count leaf'
EXPLAIN (ANALYZE, BUFFERS) SELECT count(*) FROM (SELECT 1 FROM catalog_product p WHERE (p.primary_category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/b046c3bb-67cf-575e-85de-475b0a4231db/4b68d4ca-f126-562f-a142-65edd596cc0c/%') OR EXISTS (SELECT 1 FROM catalog_product_category pc WHERE pc.product_id = p.id AND pc.category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/b046c3bb-67cf-575e-85de-475b0a4231db/4b68d4ca-f126-562f-a142-65edd596cc0c/%'))) LIMIT 10001) bounded;
\echo '=== C3 empty category'
EXPLAIN (ANALYZE, BUFFERS) SELECT p.id, p.name, p.tax_class, p.updated_at FROM catalog_product p WHERE (p.primary_category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/70134891-dc80-5215-9109-23f8f80ad40a/%') OR EXISTS (SELECT 1 FROM catalog_product_category pc WHERE pc.product_id = p.id AND pc.category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/70134891-dc80-5215-9109-23f8f80ad40a/%'))) ORDER BY p.name ASC, p.id ASC LIMIT 26;
\echo '=== C4 leaf + q "pro"'
EXPLAIN (ANALYZE, BUFFERS) SELECT p.id, p.name, p.tax_class, p.updated_at FROM catalog_product p WHERE p.name ILIKE '%pro%' AND (p.primary_category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/b046c3bb-67cf-575e-85de-475b0a4231db/4b68d4ca-f126-562f-a142-65edd596cc0c/%') OR EXISTS (SELECT 1 FROM catalog_product_category pc WHERE pc.product_id = p.id AND pc.category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/b046c3bb-67cf-575e-85de-475b0a4231db/4b68d4ca-f126-562f-a142-65edd596cc0c/%'))) ORDER BY p.name ASC, p.id ASC LIMIT 26;
\echo '=== C5 leaf + draft'
EXPLAIN (ANALYZE, BUFFERS) SELECT p.id, p.name, p.tax_class, p.updated_at FROM catalog_product p WHERE (p.primary_category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/b046c3bb-67cf-575e-85de-475b0a4231db/4b68d4ca-f126-562f-a142-65edd596cc0c/%') OR EXISTS (SELECT 1 FROM catalog_product_category pc WHERE pc.product_id = p.id AND pc.category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/b046c3bb-67cf-575e-85de-475b0a4231db/4b68d4ca-f126-562f-a142-65edd596cc0c/%'))) AND p.status='draft' ORDER BY p.name ASC, p.id ASC LIMIT 26;
\echo '=== C5c count leaf + draft'
EXPLAIN (ANALYZE, BUFFERS) SELECT count(*) FROM (SELECT 1 FROM catalog_product p WHERE (p.primary_category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/b046c3bb-67cf-575e-85de-475b0a4231db/4b68d4ca-f126-562f-a142-65edd596cc0c/%') OR EXISTS (SELECT 1 FROM catalog_product_category pc WHERE pc.product_id = p.id AND pc.category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/b046c3bb-67cf-575e-85de-475b0a4231db/4b68d4ca-f126-562f-a142-65edd596cc0c/%'))) AND p.status='draft' LIMIT 10001) bounded;
\echo '=== C6 leaf + images none'
EXPLAIN (ANALYZE, BUFFERS) SELECT p.id, p.name, p.tax_class, p.updated_at FROM catalog_product p WHERE (p.primary_category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/b046c3bb-67cf-575e-85de-475b0a4231db/4b68d4ca-f126-562f-a142-65edd596cc0c/%') OR EXISTS (SELECT 1 FROM catalog_product_category pc WHERE pc.product_id = p.id AND pc.category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/b046c3bb-67cf-575e-85de-475b0a4231db/4b68d4ca-f126-562f-a142-65edd596cc0c/%'))) AND p.images = '[]'::jsonb ORDER BY p.name ASC, p.id ASC LIMIT 26;
